# ════════════════════════════════════════════════════════════════════════
class BFPError(Exception):
    """Base error. ``to_dict()`` gives an AI-friendly, machine-readable form."""

    code = "bfp_error"

    def __init__(self, message: str, *, details: Optional[dict] = None,
                 hint: Optional[str] = None) -> None:
        super().__init__(message)
        self.details = details or {}
        self.hint = hint

    def to_dict(self) -> dict:
        out = {"error": self.code, "message": str(self)}
        if self.hint:
            out["hint"] = self.hint
        if self.details:
            out["details"] = self.details
        return out


class BfpConfigError(BFPError):
    code = "bfp_config"


class BfpBlockedError(BFPError):
    """The site served a bot-wall / CAPTCHA / hard block."""
    code = "bfp_blocked"


class DetectedError(BFPError):
    """A stealth self-check found an automation tell we could not hide."""
    code = "bfp_detected"


class ProfileError(BFPError):
    code = "bfp_profile"


class ProxyError(BFPError):
    code = "bfp_proxy"


class CaptchaError(BFPError):
    code = "bfp_captcha"


class TokenError(BFPError):
    code = "bfp_token"


class BfpGuardrailViolation(BFPError):
    code = "bfp_guardrail"


class BfpRateLimitError(BFPError):
    code = "bfp_rate_limited"


class BfpActionError(BFPError):
    code = "bfp_action"


class LaunchError(BFPError):
    code = "bfp_launch"


# ── time ────────────────────────────────────────────────────────────────
def bfp_utc_now() -> datetime:
    return datetime.now(timezone.utc)


def bfp_iso(dt: Optional[datetime] = None) -> str:
    return (dt or bfp_utc_now()).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def bfp_mono_ms() -> float:
    return time.monotonic() * 1000.0


def bfp_stamp() -> str:
    return bfp_utc_now().strftime("%Y%m%d-%H%M%S")


# ── ids ─────────────────────────────────────────────────────────────────
_ALPHABET = string.ascii_lowercase + string.digits


def token(n: int = 8) -> str:
    return "".join(secrets.choice(_ALPHABET) for _ in range(n))


def bfp_new_id(prefix: str = "id") -> str:
    return f"{prefix}_{bfp_stamp()}_{token(6)}"


def bfp_slugify(text: Any, limit: int = 50, fallback: str = "x") -> str:
    s = re.sub(r"[^a-zA-Z0-9]+", "-", str(text or "")).strip("-").lower()
    return (s[:limit].strip("-") or fallback)


def bfp_sha256_hex(data: Any) -> str:
    if isinstance(data, str):
        data = data.encode("utf-8")
    elif not isinstance(data, (bytes, bytearray)):
        data = bfp_dump_json(data).encode("utf-8")
    return hashlib.sha256(data).hexdigest()


def stable_seed(*parts: Any) -> int:
    """Deterministic 64-bit seed from any number of values."""
    return int(hashlib.sha256("|".join(map(str, parts)).encode()).hexdigest()[:16], 16)


# ── JSON ────────────────────────────────────────────────────────────────
def bfp_to_jsonable(obj: Any, _depth: int = 0) -> Any:
    if _depth > 8:
        return str(obj)
    if obj is None or isinstance(obj, (bool, int, float, str)):
        return obj
    if isinstance(obj, bytes):
        try:
            return obj.decode("utf-8")
        except UnicodeDecodeError:
            return {"_b64": base64.b64encode(obj).decode("ascii")}
    if isinstance(obj, Path):
        return str(obj)
    if isinstance(obj, datetime):
        return bfp_iso(obj)
    if is_dataclass(obj) and not isinstance(obj, type):
        return {k: bfp_to_jsonable(v, _depth + 1) for k, v in asdict(obj).items()}
    if isinstance(obj, dict):
        return {str(k): bfp_to_jsonable(v, _depth + 1) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set, deque)):
        return [bfp_to_jsonable(v, _depth + 1) for v in obj]
    if hasattr(obj, "to_dict") and callable(obj.to_dict):
        try:
            return bfp_to_jsonable(obj.to_dict(), _depth + 1)
        except Exception:  # noqa: BLE001
            pass
    return str(obj)


def bfp_dump_json(obj: Any, *, indent: Optional[int] = 2) -> str:
    return json.dumps(bfp_to_jsonable(obj), indent=indent, ensure_ascii=False, sort_keys=False)


def bfp_write_json(path: Any, obj: Any) -> Path:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(bfp_dump_json(obj), encoding="utf-8")
    return p


def bfp_read_json(path: Any, default: Any = None) -> Any:
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:  # noqa: BLE001
        return default


def bfp_write_text(path: Any, text: str) -> Path:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8")
    return p


def bfp_read_jsonl(path: Any) -> list:
    out = []
    try:
        for line in Path(path).read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line:
                out.append(json.loads(line))
    except Exception:  # noqa: BLE001
        pass
    return out


# ── URLs ────────────────────────────────────────────────────────────────
_BFP_MULTI_LABEL_SUFFIXES = {
    "co.uk", "org.uk", "ac.uk", "gov.uk", "me.uk", "com.au", "net.au", "org.au",
    "co.jp", "co.in", "com.br", "com.cn", "co.nz", "co.za", "com.tr", "co.kr",
}


def bfp_host_of(url: str) -> str:
    try:
        return (urllib.parse.urlsplit(url).hostname or "").lower()
    except Exception:  # noqa: BLE001
        return ""


def registrable_domain(host: str) -> str:
    host = (host or "").split(":")[0].strip(".").lower()
    parts = host.split(".")
    if len(parts) <= 2:
        return host
    if ".".join(parts[-2:]) in _BFP_MULTI_LABEL_SUFFIXES:
        return ".".join(parts[-3:])
    return ".".join(parts[-2:])


def is_third_party(url: str, page_host: str) -> bool:
    return bool(bfp_host_of(url)) and registrable_domain(bfp_host_of(url)) != registrable_domain(page_host)


# ════════════════════════════════════════════════════════════════════════
# logging & forensic event log (Part 45, Part 47 observability)
# ════════════════════════════════════════════════════════════════════════
import logging


class _JsonlHandler(logging.Handler):
    """Append every log record as one JSON line — forensic, greppable evidence."""

    def __init__(self, path: Any) -> None:
        super().__init__(logging.DEBUG)
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._lock = threading.Lock()
        self._fh = open(self.path, "a", encoding="utf-8", newline="\n")

    def emit(self, record: logging.LogRecord) -> None:
        try:
            line = {"ts": bfp_iso(), "level": record.levelname, "logger": record.name,
                    "message": record.getMessage()}
            extra = getattr(record, "extra_fields", None)
            if extra:
                line.update(extra)
            if record.exc_info:
                line["exc"] = self.format(record)
            with self._lock:
                self._fh.write(json.dumps(line, ensure_ascii=False) + "\n")
                self._fh.flush()
        except Exception:  # noqa: BLE001
            self.handleError(record)

    def close(self) -> None:
        try:
            self._fh.close()
        except Exception:  # noqa: BLE001
            pass
        super().close()


LOG = logging.getLogger("bfp")


def bfp_configure_logging(level: str = "INFO", *, jsonl: Any = None,
                      console: bool = True) -> logging.Logger:
    LOG.handlers.clear()
    LOG.setLevel(getattr(logging, str(level).upper(), logging.INFO))
    LOG.propagate = False
    if console:
        sh = logging.StreamHandler(sys.stderr)
        sh.setFormatter(logging.Formatter("%(asctime)s %(levelname).1s %(message)s", "%H:%M:%S"))
        LOG.addHandler(sh)
    if jsonl:
        LOG.addHandler(_JsonlHandler(jsonl))
    return LOG


class BfpEventLog:
    """Thread-safe chronological timeline (Part 45 forensic + Part 42 scoring).

    Every important thing (action, request, block, fingerprint check, proxy
    change, recovery) lands here with a monotonically increasing sequence id so
    an entire run can be reconstructed and audited after the fact.
    """

    def __init__(self, sink: Any = None) -> None:
        self._events: list = []
        self._lock = threading.Lock()
        self._seq = 0
        self.sink = Path(sink) if sink else None
        self.listeners: list = []

    def emit(self, kind: str, /, **data: Any) -> dict:
        with self._lock:
            self._seq += 1
            event = {"seq": self._seq, "ts": bfp_iso(), "t_ms": round(bfp_mono_ms(), 1), "kind": kind}
            event.update(bfp_to_jsonable(data))
            self._events.append(event)
            listeners = list(self.listeners)
        if self.sink:
            try:
                with open(self.sink, "a", encoding="utf-8", newline="\n") as fh:
                    fh.write(json.dumps(event, ensure_ascii=False) + "\n")
            except Exception:  # noqa: BLE001
                pass
        for fn in listeners:
            try:
                fn(event)
            except Exception:  # noqa: BLE001
                pass
        return event

    def events(self, kind: Optional[str] = None, **match: Any) -> list:
        with self._lock:
            items = list(self._events)
        if kind:
            items = [e for e in items if e["kind"] == kind]
        for key, value in match.items():
            items = [e for e in items if e.get(key) == value]
        return items

    def kinds(self) -> dict:
        out: dict = {}
        for e in self.events():
            out[e["kind"]] = out.get(e["kind"], 0) + 1
        return out

    def timeline(self) -> list:
        return self.events()

    def __len__(self) -> int:
        return len(self._events)

# ════════════════════════════════════════════════════════════════════════
# hooks & plugins (Part 46 — config-driven extensibility, no core changes)
# ════════════════════════════════════════════════════════════════════════
BFP_HOOK_EVENTS = (
    "session_start", "session_end", "pre_action", "post_action", "request", "response",
    "fingerprint", "detection", "blocked", "captcha", "proxy_change", "recovery",
    "profile_selected", "validation", "output", "error",
)


def _bfp_split_plugin_spec(spec: Any) -> tuple:
    """Split ``path/file.py[:Attr]`` or ``pkg.module[:Attr]`` into (target, attr).

    Cross-platform: a Windows drive letter (``C:\\`` / ``C:/``) is never treated
    as the attribute separator.
    """
    text = str(spec)
    offset = 2 if len(text) >= 3 and text[1] == ":" and text[0].isalpha() and text[2] in ("\\", "/") else 0
    head, sep, tail = text[offset:].rpartition(":")
    return (text[:offset] + head, tail) if sep else (text, "")


class BfpHookManager:
    """Register custom logic (Part 46) without touching the core engine.

    * ``hooks.on("pre_action", fn)`` / ``@hooks.on("post_action")``
    * ``hooks.register_plugin(obj)`` — methods named ``on_<event>``/``<event>``
    * ``hooks.load("my_plugin.py")`` — a file/module exposing ``register(hooks)``,
      a ``PLUGIN`` object, or module-level ``on_<event>`` functions.

    Exceptions inside handlers are isolated and recorded in ``errors``.
    """

    def __init__(self, *, strict: bool = False) -> None:
        self.strict = strict
        self._handlers: dict = {name: [] for name in BFP_HOOK_EVENTS}
        self.errors: list = []
        self.plugins: list = []

    def on(self, event: str, fn: Optional[Callable] = None):
        if event not in self._handlers:
            raise BfpConfigError(f"unknown hook event {event!r}", hint=f"use one of {BFP_HOOK_EVENTS}")
        if fn is None:
            def deco(func: Callable) -> Callable:
                self._handlers[event].append(func)
                return func
            return deco
        self._handlers[event].append(fn)
        return fn

    def has(self, event: str) -> bool:
        return bool(self._handlers.get(event))

    def register_plugin(self, plugin: Any) -> Any:
        found = 0
        for event in BFP_HOOK_EVENTS:
            for attr in (event, f"on_{event}"):
                fn = plugin.get(attr) if isinstance(plugin, dict) else getattr(plugin, attr, None)
                if callable(fn):
                    self._handlers[event].append(fn)
                    found += 1
                    break
        if not found:
            raise BfpConfigError(f"plugin {plugin!r} defines no hook handlers",
                              hint=f"define functions named like {BFP_HOOK_EVENTS[:4]}")
        self.plugins.append(plugin)
        return plugin

    def load(self, spec: str) -> Any:
        import importlib
        import importlib.util
        target, attr = _bfp_split_plugin_spec(spec)
        if target.endswith(".py") or os.path.sep in target or "/" in target:
            path = Path(target).expanduser()
            path = path if path.is_absolute() else (Path.cwd() / path)
            path = path.resolve()
            if not path.exists():
                raise BfpConfigError(f"plugin file not found: {path}")
            name = f"bfp_plugin_{bfp_slugify(path.stem, 40, 'p')}_{secrets.token_hex(2)}"
            mod_spec = importlib.util.spec_from_file_location(name, path)
            if mod_spec is None or mod_spec.loader is None:
                raise BfpConfigError(f"cannot import plugin file {path}")
            module = importlib.util.module_from_spec(mod_spec)
            sys.modules[name] = module
            mod_spec.loader.exec_module(module)
        else:
            module = importlib.import_module(target)
        obj = getattr(module, attr) if attr else module
        if attr and isinstance(obj, type):
            obj = obj()
        if not attr and callable(getattr(module, "register", None)):
            module.register(self)
            self.plugins.append(module)
            return module
        if not attr and getattr(module, "PLUGIN", None) is not None:
            obj = module.PLUGIN
            obj = obj() if isinstance(obj, type) else obj
        self.register_plugin(obj)
        return obj

    def emit(self, event: str, **payload: Any) -> list:
        results = []
        for fn in list(self._handlers.get(event, ())):
            try:
                results.append(fn(**payload))
            except Exception as exc:  # noqa: BLE001
                self.errors.append({"event": event, "handler": getattr(fn, "__name__", repr(fn)),
                                    "error": f"{type(exc).__name__}: {exc}", "ts": bfp_iso()})
                if self.strict:
                    raise
        return results

